      title = "Best the Taskmistress",
      exp = "07",
      exp_name = "Gates of Discord",
      min_lvl = 1,
      max_lvl = 125,
      quest_type = "",
      repeatable = false,
      group_size = "",
      npc = "Ranguali",
      loc = nil,
      triggers = {
        "Hail, Ranguali",
        "Who is Taskmistress Krisz?",
        "What rewards?",
        "Hail, Caridwi",
        "Through your eyes.",
        "What",
        "Hail, Caridwi the Avenged",
        "Taskmistress Krisz",
      },
      items_required = {
        { name = "her Taskmistress Krisz's Head", count = 1 },
      },
      rewards = {
        { id = 30425, name = "Block of Jade-Flecked Clay", type = "item" },
        { id = 51328, name = "Braided Horsehair Handbag", type = "item" },
        { id = 30414, name = "Centaur Figurine Sketch", type = "item" },
        { id = 30426, name = "Fur of Taskmistress Krisz", type = "item" },
