      quest_type = "",
      repeatable = false,
      group_size = "",
      npc = "Alkron Wyrmsong",
      loc = { y = 1870.0, x = 650.0, z = 320.0 },
      triggers = {
        "Hail, Alkron Wyrmsong",
        "Who is Oshiruk?",
        "Tell me of Oshiruk.",
        "What armies?",
        "What darkness?",
        "What orb?",
        "Oshiruk",
