      rewards = {
        { id = 101136, name = "Black Speckled Egg", type = "item" },
        { id = 61542, name = "Blue Speckled Egg", type = "item" },
        { id = 101144, name = "Brown Speckled Egg", type = "item" },
        { id = 59727, name = "Green Speckled Egg", type = "item" },
