    {
      id = "5803",
      title = "Jaggedpine Druid Tunic",
      exp = "03",
      exp_name = "The Shadows of Luclin",
      min_lvl = 42,
      max_lvl = 130,
      quest_type = "Quest",
      repeatable = false,
      group_size = "Solo",
